#!/usr/bin/env bash
# kitty-colors.sh — toggle kitty between dynamic (wallpaper palette) and static color schemes.
#
# Usage:
#   kitty-colors.sh dynamic          follow the wallpaper palette (noctalia template render)
#   kitty-colors.sh static <name>    use a static theme (see: kitty-colors.sh list)
#   kitty-colors.sh list             list available static themes
#   kitty-colors.sh status           show the current mode
#
# How it works: kitty.conf includes kitty-colors.conf (dynamic — regenerated by the
# noctalia theming engine on every wallpaper change). Static mode re-points the include
# line at a theme file in static-themes/, which the noctalia auto-render never touches —
# so your static scheme survives wallpaper changes.

set -euo pipefail

KCONF="$HOME/.config/kitty"
DYNAMIC_FILE="kitty-colors.conf"
STATIC_DIR="$KCONF/static-themes"
TMPL="$HOME/.config/noctalia/templates/kitty-colors-template.conf"

have() { command -v "$1" >/dev/null 2>&1; }

reload_kitty() {
    if pgrep -x kitty >/dev/null 2>&1; then
        pkill -USR1 kitty
        echo ">>    kitty reloaded"
    fi
}

set_include() { # set_include <path-relative-to-kitty-config-dir>
    local target="$1"
    if grep -qE "^include (kitty-colors|static-themes/)" "$KCONF/kitty.conf" 2>/dev/null; then
        sed -i -E "s|^include (kitty-colors\|static-themes/).*|include $target|" "$KCONF/kitty.conf"
    else
        echo "include $target" >> "$KCONF/kitty.conf"
    fi
}

current_mode() {
    local inc
    inc=$(grep -E "^include (kitty-colors|static-themes/)" "$KCONF/kitty.conf" 2>/dev/null | awk '{print $2}')
    case "$inc" in
        "$DYNAMIC_FILE") echo "dynamic" ;;
        static-themes/*) echo "static ($(basename "${inc%.conf}"))" ;;
        *) echo "unknown ($inc)" ;;
    esac
}

cmd="${1:-status}"

case "$cmd" in
    dynamic)
        set_include "$DYNAMIC_FILE"
        # re-render fresh from the currently active wallpaper (read from noctalia state)
        wp=$(grep -m1 'path = "' "$HOME/.local/state/noctalia/settings.toml" 2>/dev/null | cut -d'"' -f2)
        if [ -n "$wp" ] && [ -f "$wp" ] && have noctalia && [ -f "$TMPL" ]; then
            noctalia theme "$wp" -r "$TMPL:$KCONF/$DYNAMIC_FILE" 2>/dev/null \
                || echo "WARN  noctalia render failed — keeping the last dynamic colors"
        fi
        reload_kitty
        echo "mode: dynamic (colors follow the wallpaper)"
        ;;
    static)
        theme="${2:-}"
        if [ -z "$theme" ]; then
            echo "usage: kitty-colors.sh static <name>  (available: $(command ls "$STATIC_DIR" 2>/dev/null | sed 's/\.conf$//' | tr '\n' ' '))"
            exit 1
        fi
        src="$STATIC_DIR/$theme.conf"
        [ -f "$src" ] || { echo "theme not found: $src"; exit 1; }
        set_include "static-themes/$theme.conf"
        reload_kitty
        echo "mode: static ($theme)"
        ;;
    list)
        echo "static themes:"
        for f in "$STATIC_DIR"/*.conf; do
            [ -e "$f" ] || continue
            echo "  - $(basename "${f%.conf}")"
        done
        ;;
    status)
        echo "mode: $(current_mode)"
        ;;
    *)
        echo "usage: kitty-colors.sh {dynamic | static <name> | list | status}"
        exit 1
        ;;
esac
